نقش سازمانی: store_operations_manager (store_operations_manager)

درخواست کاربر:
وضعیت سه شعبهٔ کلیدی منطقهٔ جنوب؟ (سرپرست منطقه‌ای — جنوب)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "store_pnl",
      "description": "فروش و بودجهٔ هفتگی هر شعبه",
      "dimensions": [
        "branch",
        "week"
      ],
      "measures": [
        "sales_m",
        "budget_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "sales_per_sqm",
      "description": "فروش هر مترمربع",
      "formula": "فروش تقسیم بر مساحت فروشگاه",
      "unit": "هزار تومان",
      "dimensions": [
        "branch"
      ]
    },
    {
      "metric": "conversion_rate",
      "description": "نرخ تبدیل ترافیک به خرید",
      "formula": "تراکنش تقسیم بر بازدیدکننده",
      "unit": "درصد",
      "dimensions": [
        "branch"
      ]
    }
  ],
  "business_context": [
    "هدف‌گذاری فروش هفتگی برای هر شعبه",
    "دوربین شمارش ترافیک در ورودی همهٔ شعب",
    "استاندارد چک‌لیست ماهانه برای همهٔ شعب"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "store_pnl",
    "filters": {
      "region": "جنوب",
      "period": "this_week"
    }
  }
}

نقش سازمانی: store_operations_manager (store_operations_manager)

درخواست کاربر:
